import numpy as np
# pad missing final background cells in two known rows
for i,r in enumerate(g):
 if len(r)<25: r.extend([9]*(25-len(r)))
# connected comps per color, 4-neighbor
from collections import defaultdict, deque
comps=[]
for color in sorted(set(sum(g,[]))- {9}):
 seen=set()
 for i in range(22):
  for j in range(25):
   if g[i][j]!=color or (i,j) in seen: continue
   q=[(i,j)]; seen.add((i,j)); pts=[]
   while q:
    a,b=q.pop(); pts.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<22 and 0<=y<25 and g[x][y]==color and (x,y) not in seen: seen.add((x,y)); q.append((x,y))
   mi=min(x for x,y in pts); mj=min(y for x,y in pts)
   sh=tuple(''.join('#' if (mi+x,mj+y) in pts else '.' for y in range(max(y for x,y in pts)-mj+1)) for x in range(max(x for x,y in pts)-mi+1))
   comps.append((color,mi,mj,len(pts),sh))
for c,i,j,n,sh in comps: print(c,(i,j),n,sh)
